//! Replays the fixtures the Dart engine writes, so the Rust port keeps drawing
//! byte-identical SVG to `skribble_rough`.
//!
//! The fixtures are shared with `@skribble.dev/rough` and regenerated by
//! `dart run packages/skribble_rough/tool/js_parity_fixtures.dart`.

use std::collections::BTreeSet;
use std::f64::consts::PI;

use serde_json::Value;
use skribble_rough::DrawConfig;
use skribble_rough::DrawOptions;
use skribble_rough::Drawable;
use skribble_rough::DrawableInk;
use skribble_rough::DrawableInkOptions;
use skribble_rough::FillOptions;
use skribble_rough::FillStyle;
use skribble_rough::Filler;
use skribble_rough::Generator;
use skribble_rough::OpSetKind;
use skribble_rough::PathElementOptions;
use skribble_rough::Point;
use skribble_rough::Randomizer;
use skribble_rough::RoughPen;
use skribble_rough::RoughSvgPaths;

const FIXTURE: &str = include_str!("../../../js/rough/test/fixtures/dart-parity.json");

fn fixture() -> Value {
	serde_json::from_str(FIXTURE).expect("the parity fixture is JSON")
}

const ELEMENT_PAINT: PathElementOptions<'static> = PathElementOptions {
	stroke: "#222",
	fill: "rgb(1, 2, 3)",
	stroke_width: 1.5,
	sketch_width: 1.0,
	non_scaling_stroke: false,
};

/// A fixture shape name and how to draw it.
type ShapeCase = (&'static str, fn(&mut Generator) -> Drawable);

/// The shapes the Dart tool draws, by fixture name.
const SHAPES: &[ShapeCase] = &[
	("rectangle", |g| g.rectangle(4.0, 4.0, 192.0, 92.0)),
	("smallRectangle", |g| g.rectangle(2.0, 3.0, 30.0, 20.0)),
	("ellipse", |g| g.ellipse(100.0, 50.0, 180.0, 80.0)),
	("circle", |g| g.circle(40.0, 40.0, 60.0)),
	("shortLine", |g| g.line(10.0, 10.0, 40.0, 30.0)),
	("longLine", |g| g.line(5.0, 5.0, 400.0, 120.0)),
	("veryLongLine", |g| g.line(0.0, 0.0, 900.0, 40.0)),
	("polygon", |g| {
		g.polygon(&points(&[
			(10.0, 80.0),
			(60.0, 5.0),
			(120.0, 70.0),
			(80.0, 110.0),
			(30.0, 100.0),
		]))
	}),
	("linearPath", |g| {
		g.linear_path(&points(&[(5.0, 5.0), (80.0, 30.0), (20.0, 70.0)]), true)
	}),
	("arc", |g| {
		g.arc(100.0, 100.0, 160.0, 120.0, 0.3, PI * 1.4, false)
	}),
	("closedArc", |g| {
		g.arc(100.0, 100.0, 160.0, 120.0, -0.5, PI, true)
	}),
	("curve", |g| {
		g.curve(&points(&[
			(4.0, 50.0),
			(40.0, 10.0),
			(80.0, 40.0),
			(116.0, 12.0),
		]))
	}),
	("threePointCurve", |g| {
		g.curve(&points(&[(4.0, 50.0), (40.0, 10.0), (80.0, 40.0)]))
	}),
	("roundedRectangle", |g| {
		g.rounded_rectangle(4.0, 4.0, 220.0, 64.0, [16.0; 4])
	}),
	("mixedRoundedRectangle", |g| {
		g.rounded_rectangle(2.0, 2.0, 90.0, 40.0, [4.0, 12.0, 0.0, 30.0])
	}),
];

fn points(pairs: &[(f64, f64)]) -> Vec<Point> {
	pairs.iter().copied().map(Point::from).collect()
}

fn fill_style(dart_name: &str) -> FillStyle {
	match dart_name {
		"none" => FillStyle::None,
		"hachure" => FillStyle::Hachure,
		"crossHatch" => FillStyle::CrossHatch,
		"zigzag" => FillStyle::ZigZag,
		"dashed" => FillStyle::Dashed,
		"dots" => FillStyle::Dots,
		"solid" => FillStyle::Solid,
		other => panic!("the fixture uses an unknown fill style `{other}`"),
	}
}

fn pen(name: Option<&str>) -> RoughPen {
	match name {
		None | Some("ink") => RoughPen::INK,
		Some("uniform") => RoughPen::UNIFORM,
		Some("fineliner") => RoughPen::FINELINER,
		Some("brush") => RoughPen::BRUSH,
		Some(other) => panic!("the fixture uses an unknown pen `{other}`"),
	}
}

fn generator(options: DrawOptions, style: FillStyle) -> Generator {
	let pattern = FillOptions {
		hachure_gap: 8.0,
		..FillOptions::default()
	};
	Generator::new(
		DrawConfig::new(options),
		Filler::new(style, pattern, DrawConfig::new(options)),
	)
}

/// FNV-1a over UTF-16 code units, with the length, as the Dart tool writes
/// it.
fn digest(value: &str) -> String {
	let mut hash: u32 = 0x811c_9dc5;
	let mut length = 0;
	for unit in value.encode_utf16() {
		hash = (hash ^ u32::from(unit)).wrapping_mul(0x0100_0193);
		length += 1;
	}
	format!("{hash:08x}:{length}")
}

fn text(value: &Value) -> &str {
	value.as_str().expect("a fixture string")
}

#[test]
fn replays_darts_random_stream() {
	for case in fixture()["randoms"].as_array().expect("random cases") {
		let seed = case["seed"].as_i64().expect("an integer seed");
		let mut random = Randomizer::new(seed);
		for expected in case["values"].as_array().expect("random values") {
			let expected = expected.as_f64().expect("a double");
			assert_eq!(random.next_double(), expected, "seed {seed}");
		}
	}
}

#[test]
fn covers_every_shape_in_the_fixture() {
	let fixture = fixture();
	let in_fixture: BTreeSet<&str> = fixture["cases"]
		.as_array()
		.expect("cases")
		.iter()
		.map(|case| text(&case["shape"]))
		.collect();
	let ported: BTreeSet<&str> = SHAPES.iter().map(|(name, _)| *name).collect();
	assert_eq!(in_fixture, ported);
}

#[test]
fn renders_the_sample_rectangle_byte_for_byte() {
	let options = DrawOptions {
		seed: 7,
		roughness: 1.2,
		..DrawOptions::default()
	};
	let drawable = generator(options, FillStyle::Hachure).rectangle(4.0, 4.0, 192.0, 92.0);
	let svg = RoughSvgPaths::from_drawable(&drawable);
	assert_eq!(
		svg.to_path_elements(&ELEMENT_PAINT),
		text(&fixture()["sample"]["elements"])
	);
}

#[test]
fn draws_every_case_like_dart() {
	let fixture = fixture();
	let cases = fixture["cases"].as_array().expect("cases");
	assert!(!cases.is_empty());

	for case in cases {
		let name = format!(
			"{} · {} · seed {} · roughness {} · {} pen",
			text(&case["shape"]),
			text(&case["fillStyle"]),
			case["seed"],
			case["roughness"],
			case["pen"].as_str().unwrap_or("ink"),
		);
		let options = DrawOptions {
			seed: case["seed"].as_i64().expect("an integer seed"),
			roughness: case["roughness"].as_f64().expect("a roughness"),
			pen: pen(case["pen"].as_str()),
			..DrawOptions::default()
		};
		let (_, draw) = SHAPES
			.iter()
			.find(|(shape, _)| *shape == text(&case["shape"]))
			.expect("every fixture shape is ported");
		let drawable = draw(&mut generator(
			options,
			fill_style(text(&case["fillStyle"])),
		));

		let svg = RoughSvgPaths::from_drawable(&drawable);
		let expected = &case["svg"];
		assert_eq!(
			digest(&svg.outline),
			text(&expected["outline"]),
			"{name}: outline"
		);
		assert_eq!(
			digest(&svg.sketch),
			text(&expected["sketch"]),
			"{name}: sketch"
		);
		assert_eq!(
			digest(&svg.solid),
			text(&expected["solid"]),
			"{name}: solid"
		);
		assert_eq!(
			digest(&svg.to_path_elements(&ELEMENT_PAINT)),
			text(&expected["elements"]),
			"{name}: elements"
		);

		let ink: Vec<String> = DrawableInk::new(&drawable, DrawableInkOptions::new(2.0, 1.0))
			.svg_paths()
			.into_iter()
			.filter(|path| path.filled && path.kind != OpSetKind::FillPath)
			.map(|path| {
				let kind = match path.kind {
					OpSetKind::Path => "path",
					OpSetKind::FillSketch => "fillSketch",
					OpSetKind::FillPath => "fillPath",
				};
				digest(&format!("{kind} {}", path.data))
			})
			.collect();
		let expected_ink: Vec<&str> = case["ink"]
			.as_array()
			.expect("ink digests")
			.iter()
			.map(text)
			.collect();
		assert_eq!(ink, expected_ink, "{name}: ink");
	}
}
